"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["64073"],{162974(_){_.exports=JSON.parse('{"id":7784,"title":"3\u672C\u4E66\u6BD4\u8F83\u63D0\u793A\u8BCD","description":"\u4F60\u597D\u3002\u4F5C\u4E3A\u4E00\u540D\u81F4\u529B\u4E8E\u7EC8\u8EAB\u5B66\u4E60\u7684\u8BFB\u4E66\u7231\u597D\u8005\uFF0C\u8FD9\u4E09\u672C\u4E66\u2014\u2014\u300A\u7EB3\u74E6\u5C14\u5B9D\u5178\u300B\uFF08The Almanack of Naval Ravikant\uFF09\u3001\u300A\u7A77\u67E5\u7406\u5B9D\u5178\u300B\uFF08Poor Charlie\'s Almanack\uFF09\u548C\u300A\u539F\u5219\u300B\uFF08Principles\uFF09\u2014\u2014\u786E\u5B9E\u6784\u6210\u4E86\u73B0\u4EE3\u4EBA\u8FFD\u6C42\u8D22\u5BCC\u3001\u667A\u6167\u4E0E\u5E78\u798F\u7684\u201C\u4E09\u4F4D\u4E00\u4F53\u201D\u5723\u7ECF\u3002\\n\u5B83\u4EEC\u5206\u522B\u4EE3\u8868\u4E86\u4E09\u79CD\u4E0D\u540C\u7EF4\u5EA6\u7684\u9876\u7EA7\u667A\u6167\uFF1A\u7EB3\u74E6\u5C14\u4EE3\u8868\u4E86\u7845\u8C37\u7684\u6570\u5B57\u65F6\u4EE3\u54F2\u5B66\uFF0C\u67E5\u7406\u2022\u8292\u683C\u4EE3\u8868\u4E86\u4F20\u7EDF\u7684\u666E\u4E16\u667A\u6167\u4E0E\u5B66\u9662\u6D3E\u7406\u6027\uFF0C\u800C\u745E\u2022\u8FBE\u5229\u6B27\u5219\u4EE3\u8868\u4E86\u6781\u5EA6\u6C42\u771F\u7684\u7CFB\u7EDF\u5316\u5DE5\u7A0B\u601D\u7EF4\u3002\\n\u4EE5\u4E0B\u662F\u6211\u5BF9\u8FD9\u4E09\u672C\u4E66\u7684\u6DF1\u5EA6\u5BF9\u6BD4\u5206\u6790\uFF1A\\n________________________________________\\n\u4E00\u3001 \u6838\u5FC3\u89C2\u70B9\u5BF9\u6BD4\\n1. \u5404\u4E66\u6838\u5FC3\u89C2\u70B9\u6982\u89C8\\n\u2022\\t\u300A\u7EB3\u74E6\u5C14\u5B9D\u5178\u300B\uFF1A\u6760\u6746\u4E0E\u5E78\u798F\u7684\u73B0\u4EE3\u89E3\u6CD5\\no\\t\u6838\u5FC3\u8BCD\uFF1A \u4E13\u957F\uFF08Specific Knowledge\uFF09\u3001\u6760\u6746\uFF08Leverage\uFF09\u3001\u590D\u5229\u3001\u5185\u5FC3\u7684\u5E73\u9759\u3002\\no\\t\u4E3B\u5F20\uFF1A \u8D22\u5BCC\u662F\u4F60\u5728\u7761\u89C9\u65F6\u4E5F\u80FD\u8D5A\u94B1\u7684\u8D44\u4EA7\uFF0C\u800C\u975E\u51FA\u5356\u65F6\u95F4\u7684\u85AA\u6C34\u3002\u901A\u8FC7\u201C\u4EA7\u54C1\u5316\u4F60\u81EA\u5DF1\u201D\uFF08Productize Yourself\uFF09\uFF0C\u5229\u7528\u4EE3\u7801\u548C\u5A92\u4F53\u8FD9\u7C7B\u96F6\u8FB9\u9645\u6210\u672C\u7684\u6760\u6746\uFF0C\u5B9E\u73B0\u8D22\u5BCC\u81EA\u7531\u3002\u540C\u65F6\uFF0C\u5E78\u798F\u662F\u4E00\u79CD\u53EF\u4EE5\u4E60\u5F97\u7684\u6280\u80FD\uFF0C\u6E90\u4E8E\u51CF\u5C11\u6B32\u671B\u548C\u6D3B\u5728\u5F53\u4E0B\u3002\\n\u2022\\t\u300A\u7A77\u67E5\u7406\u5B9D\u5178\u300B\uFF1A\u666E\u4E16\u667A\u6167\u4E0E\u591A\u5143\u601D\u7EF4\u6A21\u578B\\no\\t\u6838\u5FC3\u8BCD\uFF1A \u591A\u5143\u601D\u7EF4\u6A21\u578B\uFF08Mental Models\uFF09\u3001\u9006\u5411\u601D\u8003\uFF08Inversion\uFF09\u3001\u80FD\u529B\u5708\u3001\u4EBA\u7C7B\u8BEF\u5224\u5FC3\u7406\u5B66\u3002\\no\\t\u4E3B\u5F20\uFF1A \u624B\u91CC\u62FF\u7740\u94C1\u9524\u7684\u4EBA\uFF0C\u770B\u4EC0\u4E48\u90FD\u50CF\u9489\u5B50\u3002\u8292\u683C\u5F3A\u8C03\u5FC5\u987B\u638C\u63E1\u591A\u4E2A\u5B66\u79D1\uFF08\u7269\u7406\u3001\u751F\u7269\u3001\u5FC3\u7406\u5B66\u7B49\uFF09\u7684\u6838\u5FC3\u6A21\u578B\uFF0C\u5F62\u6210\u201C\u683C\u6805\u7406\u8BBA\u201D\uFF08Lollapalooza Effect\uFF09\uFF0C\u4EE5\u907F\u514D\u5355\u4E00\u89C6\u89D2\u7684\u76F2\u533A\u3002\u6210\u529F\u66F4\u591A\u6765\u81EA\u4E8E\u201C\u907F\u514D\u611A\u8822\u201D\uFF0C\u800C\u975E\u8FFD\u6C42\u7EDD\u9876\u806A\u660E\u3002\\n\u2022\\t\u300A\u539F\u5219\u300B\uFF1A\u50CF\u673A\u5668\u4E00\u6837\u8FDB\u5316\u7684\u7CFB\u7EDF\u8BBA\\no\\t\u6838\u5FC3\u8BCD\uFF1A \u6781\u5EA6\u6C42\u771F\uFF08Radical Truth\uFF09\u3001\u6781\u5EA6\u900F\u660E\u3001\u521B\u610F\u62E9\u4F18\u3001\u75DB\u82E6+\u53CD\u601D=\u8FDB\u6B65\u3002\\no\\t\u4E3B\u5F20\uFF1A \u5C06\u751F\u6D3B\u548C\u5DE5\u4F5C\u89C6\u4E3A\u673A\u5668\u3002\u73B0\u5B9E\u662F\u5BA2\u89C2\u5B58\u5728\u7684\uFF0C\u4E0D\u8981\u56E0\u4E3A\u73B0\u5B9E\u4E0D\u7B26\u5408\u4F60\u7684\u613F\u671B\u800C\u6124\u6012\u3002\u901A\u8FC7\u8BB0\u5F55\u51B3\u7B56\u3001\u5EFA\u7ACB\u7B97\u6CD5\u3001\u4ECE\u9519\u8BEF\u4E2D\u5B66\u4E60\uFF0C\u4E0D\u65AD\u4F18\u5316\u4F60\u7684\u201C\u673A\u5668\u201D\uFF0C\u5B9E\u73B0\u4E2A\u4EBA\u7684\u8FDB\u5316\u3002\\n2. \u5171\u540C\u70B9\u4E0E\u4E0D\u540C\u70B9\\n\u2022\\t\u5171\u540C\u70B9\uFF1A\\no\\t\u6781\u5EA6\u7406\u6027\uFF1A \u4E09\u8005\u90FD\u6781\u5EA6\u63A8\u5D07\u7406\u6027\uFF0C\u53CD\u5BF9\u60C5\u7EEA\u5316\u51B3\u7B56\uFF0C\u5F3A\u8C03\u9762\u5BF9\u73B0\u5B9E\uFF08Reality\uFF09\u3002\\no\\t\u957F\u671F\u4E3B\u4E49\uFF1A \u90FD\u76F8\u4FE1\u590D\u5229\u7684\u529B\u91CF\uFF0C\u65E0\u8BBA\u662F\u8D22\u5BCC\u3001\u77E5\u8BC6\u8FD8\u662F\u4EBA\u9645\u5173\u7CFB\u3002\\no\\t\u7EC8\u8EAB\u5B66\u4E60\uFF1A \u90FD\u8BA4\u4E3A\u6301\u7EED\u7684\u77E5\u8BC6\u8F93\u5165\u662F\u7ADE\u4E89\u4F18\u52BF\u7684\u6838\u5FC3\u3002\\n\u2022\\t\u4E0D\u540C\u70B9\uFF08\u7EF4\u5EA6\u7684\u5DEE\u5F02\uFF09\uFF1A\\no\\t\u89C6\u89D2\u4E0D\u540C\uFF1A \u7EB3\u74E6\u5C14\u5173\u6CE8\u4E2A\u4F53\uFF08\u5982\u4F55\u5728\u73B0\u4EE3\u793E\u4F1A\u5355\u5175\u4F5C\u6218\u5E76\u83B7\u5F97\u81EA\u7531\uFF09\uFF1B\u8FBE\u5229\u6B27\u5173\u6CE8\u7EC4\u7EC7\u4E0E\u7CFB\u7EDF\uFF08\u5982\u4F55\u5EFA\u7ACB\u673A\u5236\u6765\u4FEE\u6B63\u9519\u8BEF\uFF09\uFF1B\u8292\u683C\u5173\u6CE8\u8BA4\u77E5\u6846\u67B6\uFF08\u5982\u4F55\u901A\u8FC7\u601D\u7EF4\u6A21\u578B\u7406\u89E3\u4E16\u754C\uFF09\u3002\\no\\t\u884C\u52A8\u6307\u5357\u4E0D\u540C\uFF1A \u7EB3\u74E6\u5C14\u66F4\u50CF\u662F\u4E00\u4E2A\u54F2\u5B66\u5BB6\uFF0C\u544A\u8BC9\u4F60\u201C\u65B9\u5411\u201D\uFF1B\u8FBE\u5229\u6B27\u50CF\u4E00\u4E2A\u5DE5\u7A0B\u5E08\uFF0C\u7ED9\u4F60\u201C\u56FE\u7EB8\u201D\u548C\u201C\u7B97\u6CD5\u201D\uFF1B\u8292\u683C\u50CF\u4E00\u4E2A\u5386\u53F2\u667A\u8005\uFF0C\u7ED9\u4F60\u201C\u8B66\u793A\u201D\u548C\u201C\u601D\u7EF4\u5DE5\u5177\u7BB1\u201D\u3002\\n________________________________________\\n\u4E8C\u3001 \u4EBA\u751F\u542F\u53D1\\n1. \u300A\u7EB3\u74E6\u5C14\u5B9D\u5178\u300B\uFF1A\u5E78\u798F\u662F\u5F53\u4E0B\u7684\u9009\u62E9\\n\u2022\\t\u91CD\u8981\u5EFA\u8BAE\uFF1A \u201C\u5982\u679C\u6709\u4EC0\u4E48\u4E8B\u60C5\u662F\u4F60\u4EE5\u540E\u60F3\u505A\u7684\uFF0C\u73B0\u5728\u5C31\u53BB\u505A\u3002\u4EBA\u751F\u6CA1\u6709\u5F69\u6392\u3002\u201D\\n\u2022\\t\u6211\u7684\u542F\u53D1\uFF1A \u7EB3\u74E6\u5C14\u6700\u5927\u7684\u542F\u53D1\u5728\u4E8E**\u201C\u89E3\u7ED1\u201D**\u3002\u4ED6\u6559\u5BFC\u6211\u4EEC\u5C06\u201C\u8D22\u5BCC\u201D\u4E0E\u201C\u65F6\u95F4\u201D\u89E3\u7ED1\uFF0C\u5C06\u201C\u5E78\u798F\u201D\u4E0E\u201C\u5916\u7269\u201D\u89E3\u7ED1\u3002\\no\\t\u4F8B\u5B50\uFF1A \u7EB3\u74E6\u5C14\u8BF4\uFF1A\u201C\u6B32\u671B\u5C31\u662F\u4F60\u8DDF\u81EA\u5DF1\u7B7E\u7684\u5408\u540C\uFF0C\u4E0D\u5F97\u5230\u60F3\u8981\u7684\u4E1C\u897F\u5C31\u4E0D\u5FEB\u4E50\u3002\u201D\u8FD9\u8BA9\u6211\u610F\u8BC6\u5230\uFF0C\u7126\u8651\u5F80\u5F80\u6E90\u4E8E\u5BF9\u672A\u6765\u7684\u8FC7\u5EA6\u671F\u5F85\uFF0C\u771F\u6B63\u7684\u81EA\u7531\u4E0D\u4EC5\u662F\u8D22\u52A1\u81EA\u7531\uFF0C\u66F4\u662F\u5185\u5FC3\u7684\u65E0\u62D8\u65E0\u675F\u3002\\n2. \u300A\u7A77\u67E5\u7406\u5B9D\u5178\u300B\uFF1A\u53CD\u8FC7\u6765\u60F3\uFF0C\u603B\u662F\u53CD\u8FC7\u6765\u60F3\\n\u2022\\t\u91CD\u8981\u5EFA\u8BAE\uFF1A \u201C\u6211\u53EA\u60F3\u77E5\u9053\u6211\u5C06\u6765\u4F1A\u6B7B\u5728\u4EC0\u4E48\u5730\u65B9\uFF0C\u8FD9\u6837\u6211\u5C31\u6C38\u8FDC\u4E0D\u53BB\u90A3\u91CC\u3002\u201D\\n\u2022\\t\u6211\u7684\u542F\u53D1\uFF1A \u8292\u683C\u7684**\u201C\u9006\u5411\u601D\u7EF4\u201D**\u662F\u89E3\u51B3\u4EBA\u751F\u96BE\u9898\u7684\u795E\u5668\u3002\u60F3\u8981\u5E78\u798F\uFF1F\u5148\u7814\u7A76\u4EC0\u4E48\u8BA9\u4EBA\u75DB\u82E6\uFF08\u5AC9\u5992\u3001\u6028\u6068\u3001\u81EA\u601C\uFF09\u3002\u60F3\u8981\u81F4\u5BCC\uFF1F\u5148\u7814\u7A76\u4EC0\u4E48\u8BA9\u4EBA\u7834\u4EA7\uFF08\u52A0\u6760\u6746\u3001\u751A\u81F3\u5B64\u6CE8\u4E00\u63B7\uFF09\u3002\\no\\t\u4F8B\u5B50\uFF1A \u5728\u505A\u51B3\u7B56\u65F6\uFF0C\u6211\u4E0D\u518D\u53EA\u95EE\u201C\u600E\u4E48\u505A\u80FD\u6210\u529F\u201D\uFF0C\u800C\u662F\u5148\u95EE\u201C\u600E\u4E48\u505A\u4E00\u5B9A\u4F1A\u641E\u7838\u201D\uFF0C\u7136\u540E\u907F\u5F00\u8FD9\u4E9B\u5751\u3002\u8FD9\u663E\u8457\u964D\u4F4E\u4E86\u751F\u6D3B\u4E2D\u7684\u707E\u96BE\u6027\u98CE\u9669\u3002\\n3. \u300A\u539F\u5219\u300B\uFF1A\u62E5\u62B1\u73B0\u5B9E\uFF0C\u62E5\u62B1\u75DB\u82E6\\n\u2022\\t\u91CD\u8981\u5EFA\u8BAE\uFF1A \u201C\u75DB\u82E6+\u53CD\u601D=\u8FDB\u6B65\u3002\u201D\\n\u2022\\t\u6211\u7684\u542F\u53D1\uFF1A \u8FBE\u5229\u6B27\u5C06\u9519\u8BEF\u548C\u75DB\u82E6\u89C6\u4E3A**\u201C\u8FDB\u5316\u7684\u71C3\u6599\u201D**\u3002\u5927\u591A\u6570\u4EBA\u901A\u8FC7\u63A9\u76D6\u9519\u8BEF\u6765\u4FDD\u62A4\u81EA\u5C0A\uFF0C\u4F46\u8FBE\u5229\u6B27\u5EFA\u8BAE\u6211\u4EEC\u628A\u9519\u8BEF\u6446\u5728\u684C\u9762\u4E0A\u8FDB\u884C\u201C\u5C38\u68C0\u201D\u3002\\no\\t\u4F8B\u5B50\uFF1A \u73B0\u5728\u7684\u6211\u5728\u9047\u5230\u632B\u6298\u65F6\uFF0C\u4F1A\u5F3A\u5236\u81EA\u5DF1\u8FDB\u5165\u201C\u89C2\u5BDF\u8005\u6A21\u5F0F\u201D\uFF0C\u628A\u75DB\u82E6\u89C6\u4E3A\u4E00\u4E2A\u4FE1\u53F7\uFF0C\u63D0\u9192\u6211\u5F53\u4E0B\u7684\u601D\u7EF4\u6A21\u578B\u4E0E\u73B0\u5B9E\u4E0D\u7B26\uFF0C\u9700\u8981\u4FEE\u6B63\u3002\u8FD9\u79CD\u5FC3\u6001\u8BA9\u201C\u5931\u8D25\u201D\u53D8\u5F97\u4E0D\u518D\u53EF\u6015\uFF0C\u751A\u81F3\u53D8\u5F97\u6709\u4EF7\u503C\u3002\\n________________________________________\\n\u4E09\u3001 \u8D22\u5BCC\u77E5\u8BC6\\n1. \u6559\u6388\u7684\u8D22\u5BCC\u903B\u8F91\\n\u2022\\t\u7EB3\u74E6\u5C14\uFF08\u521B\u9020\u8005\u89C6\u89D2\uFF09\uFF1A\\no\\t\u6838\u5FC3\u903B\u8F91\uFF1A \u5BFB\u627E\u5E76\u6784\u5EFA\u6760\u6746\u3002\\no\\t\u5177\u4F53\u5E94\u7528\uFF1A \u73B0\u4EE3\u793E\u4F1A\u6709\u56DB\u79CD\u6760\u6746\uFF1A\u52B3\u52A8\u529B\uFF08\u6700\u5F31\uFF09\u3001\u8D44\u672C\uFF08\u9700\u8981\u94B1\uFF09\u3001\u4EE3\u7801\uFF08\u65E0\u9700\u8BB8\u53EF\uFF09\u3001\u5A92\u4F53\uFF08\u65E0\u9700\u8BB8\u53EF\uFF09\u3002\u7EB3\u74E6\u5C14\u5EFA\u8BAE\u666E\u901A\u4EBA\u901A\u8FC7\u4E92\u8054\u7F51\uFF08\u4EE3\u7801\u548C\u5A92\u4F53\uFF09\u653E\u5927\u81EA\u5DF1\u7684\u201C\u4E13\u957F\u201D\u3002\\no\\t\u4EF7\u503C\uFF1A \u6781\u5176\u9002\u5408\u6570\u5B57\u6E38\u6C11\u3001\u521B\u4E1A\u8005\u548C\u5185\u5BB9\u521B","owner":"Dortha","upvotes":6,"downvotes":0,"upvoteDifference":6,"updatedAt":"2026-06-19T15:29:35.286Z"}')}}]);